nsresult nsMsgSearchTerm::MatchBody(nsIMsgSearchScopeTerm* scope,
                                    const char* msgCharset, nsIMsgDBHdr* msg,
                                    bool* pResult) {
  NS_ENSURE_ARG_POINTER(pResult);
  nsresult rv = NS_OK;
  *pResult = false;

  // Change the sense of the loop so we don't bail out prematurely
  // on negative terms. i.e. opDoesntContain must look at all lines
  bool boolContinueLoop;
  GetMatchAllBeforeDeciding(&boolContinueLoop);
  bool result = boolContinueLoop;

  nsCString compare;
  nsMsgBodyHandler bodyHandler(scope, msg);
  uint32_t seen = 0;
  // Kept outside the loop because GetNextLine() does not set it at EOF, and
  // text accumulated in `compare` must be matched with its part's charset.
  nsAutoCString charset;
  while (result == boolContinueLoop) {
    // Small hack so we don't look all through a message when someone has
    // specified "BODY IS foo".
    if (m_operator == nsMsgSearchOp::Is || m_operator == nsMsgSearchOp::Isnt) {
      if (seen > m_value.utf8String.Length()) {
        break;
      }
    }

    nsAutoCString buf;
    bool needsQPReset = false;
    int32_t n = bodyHandler.GetNextLine(buf, charset, needsQPReset);
    bool eof = n < 0;
    if (!eof) {
      seen += n;
      bool softLineBreak = false;
      // Do in-place decoding of quoted printable
      if (bodyHandler.IsQP()) {
        softLineBreak = StringEndsWith(buf, "="_ns);
        MsgStripQuotedPrintable(buf);
        // If soft line break, chop off the last char as well.
        size_t bufLength = buf.Length();
        if ((bufLength > 0) && softLineBreak) buf.SetLength(bufLength - 1);
      }
      if (needsQPReset) {
        bodyHandler.resetQP();
      }
      // Take only as much as we're prepared to convert to UTF-16 in one go.
      // A part which is one endless run of soft line breaks would otherwise
      // arrive here in one piece, and so would a body written as a single
      // very long line.
      const uint32_t limit = mozilla::StaticPrefs::mail_search_max_body_bytes();
      if (compare.Length() < limit) {
        compare.Append(StringHead(buf, limit - compare.Length()));
      }
      // If this line ends with a soft line break, loop around and get the
      // next line before looking for the search string. A malformed message
      // may end on a soft line break; we then match the leftover text at EOF
      // below. Once the cap is reached matching happens in chunks, just as it
      // does line by line for text that isn't quoted-printable.
      if (softLineBreak && compare.Length() < limit) continue;
    }
    if (!compare.IsEmpty()) {
      char startChar = (char)compare.CharAt(0);
      if (startChar != '\r' && startChar != '\n') {
        rv = MatchString(
            compare, charset.IsEmpty() ? msgCharset : charset.get(), &result);
      }
      compare.Truncate();
    }
    if (eof) {
      break;
    }
  }

  *pResult = result;
  return rv;
}
